#!/bin/sh
# Reproduction on CURRENT main: a fresh copy of work/enclave (its working copy, without .git, node_modules or target;
# main's installed node_modules linked read-only), patches 07-09 applied (dry run first), every result compared with
# INVENTORY.txt, the shared vectors checked unchanged (history: regenerated by the SDK and compared; checkpoint: as
# delivered, not regenerated), then Go (every tag set) and the JS suites of every touched file. The anvil rigs ran on
# the candidate tree (job-rig); main's later edits (base/main-moved.txt) touch none of their files.
set -e
W=/home/steven/Documents/Codex/2026-10-18/wo/work; H=$W/history-checkpoint-transport; R=$H/repro
rm -rf $R; mkdir -p $R
rsync -a --exclude .git --exclude node_modules --exclude target --exclude custody/dkg $W/enclave/ $R/
for d in node_modules network/node_modules relay/node_modules sdk/sessions/node_modules; do ln -s $W/enclave/$d $R/$d; done
cd $R
for p in $H/patches/0*.patch; do patch -p1 --dry-run -s < $p; done
for p in $H/patches/0*.patch; do patch -p1 -s < $p; done
while read p h r f; do [ "$(sha256sum < $f | cut -c1-64)" = "$r" ] || { echo "MISMATCH $f"; exit 1; }; done < $H/patches/INVENTORY.txt
echo PATCHES-APPLIED-AND-MATCH
cp isolation/m2/bootstrap/testdata/history-vectors.json /tmp/hv.$$ && node scripts/history-vectors.mjs && cmp /tmp/hv.$$ isolation/m2/bootstrap/testdata/history-vectors.json && rm /tmp/hv.$$
echo VECTORS-REPRODUCED
export GOFLAGS=-mod=mod
cd $R/isolation/m2
go vet ./appconfig ./release ./bootstrap ./front
go vet -tags bootstrapdirect ./front
go vet -tags "shielddirect bootstrapdirect" ./front
go build ./... && go build -o /dev/null -tags bootstrapdirect ./front && go build -o /dev/null -tags "shielddirect bootstrapdirect" ./front
(cd ../m3 && go vet ./secretrun && go test -count=1 ./secretrun)
go test -count=1 -p 1 ./appconfig ./release ./bootstrap ./front
go test -count=1 -p 1 -tags bootstrapdirect ./front
go test -count=1 -p 1 -tags "shielddirect bootstrapdirect" ./front
echo GO-OK
cd $R
node --test --test-concurrency=1 test/history-checkpoint-transport.test.mjs test/history-owner-tools.test.mjs test/bootstrap-package.test.mjs \
  test/bootstrap-names.test.mjs test/site-independent-names.test.mjs test/site-independent-storage.test.mjs \
  test/bootstrap-supervisor.test.mjs test/direct-only-supervisor.test.mjs test/startup-expectation.test.mjs \
  test/windows-shield-startup.test.mjs test/windows-shield-package-transport.test.mjs
GIT_DIR=$W/enclave/.git GIT_WORK_TREE=$R GIT_OPTIONAL_LOCKS=0 node --test --test-concurrency=1 test/site-independent-management-unit.test.mjs
echo JS-PACKAGE-OK
node --test --test-concurrency=1 test/cli.test.mjs
echo CLI-OK
